function Reveal({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  const reduced = useReducedMotion();
  return <motion.div className={className} initial={reduced ? false : { opacity: 0, y: 22 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: .18 }} transition={{ duration: .55, ease: "easeOut" }}>{children}</motion.div>;
}
function SectionTitle({ eyebrow, title, intro }: { eyebrow: string; title: string; intro?: string }) {
  return <div className="max-w-3xl"><p className="section-eyebrow">{eyebrow}</p><h2 className="mt-3 text-3xl font-semibold leading-tight md:text-5xl">{title}</h2>{intro && <p className="mt-5 max-w-2xl text-base leading-7 text-muted-foreground md:text-lg">{intro}</p>}</div>;
}
function scrollTo(id: string) { document.getElementById(id)?.scrollIntoView({ behavior: "smooth", block: "start" }); }

function LanguageSwitcher({ locale, label }: { locale: Locale; label: string }) {
  const other = locale === "pt" ? "en" : "pt";
  const change = () => { document.cookie = `gpmb_locale=${other};path=/;max-age=31536000;samesite=lax`; };
  return <Link href={`/${other}`} onClick={change} aria-label={`${label}: ${other.toUpperCase()}`} className="inline-flex h-10 items-center gap-2 rounded-lg border border-border bg-background px-3 text-xs font-semibold tracking-[.08em] text-foreground transition hover:border-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"><Globe2 className="size-4 text-primary"/><span className={locale === "pt" ? "text-primary" : "text-muted-foreground"}>PT</span><span aria-hidden="true">|</span><span className={locale === "en" ? "text-primary" : "text-muted-foreground"}>EN</span></Link>;
}

function Header({ m, locale }: { m: Messages; locale: Locale }) {
  const [open, setOpen] = useState(false); const [scrolled, setScrolled] = useState(false); const [active, setActive] = useState<NavId>("home");
  useEffect(() => { const onScroll = () => setScrolled(window.scrollY > 20); onScroll(); window.addEventListener("scroll", onScroll, { passive: true }); return () => window.removeEventListener("scroll", onScroll); }, []);
  useEffect(() => { const observer = new IntersectionObserver((entries) => entries.forEach(e => { if (e.isIntersecting) setActive(e.target.id as NavId); }), { rootMargin: "-30% 0px -60%", threshold: .01 }); navIds.forEach(id => { const el = document.getElementById(id); if (el) observer.observe(el); }); return () => observer.disconnect(); }, []);
  const go = (id: NavId) => { setOpen(false); scrollTo(id); };
  return <header className={`fixed inset-x-0 top-0 z-50 transition-all duration-300 ${scrolled ? "bg-background/95 shadow-header backdrop-blur-xl" : "bg-background/80 backdrop-blur-sm"}`}>
    <a href="#main" className="skip-link">{m.nav.skip}</a>
    <div className="mx-auto flex h-[76px] max-w-7xl items-center justify-between px-5 lg:px-8">
      <button onClick={() => go("home")} className="cursor-pointer border-0 bg-transparent p-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" aria-label={m.nav.home}><img src="/images/gpmb-logo.png" alt="GPMB, Lda" className="h-12 w-auto max-w-[210px] object-contain object-left" /></button>
      <nav aria-label="Primary" className="hidden items-center gap-6 lg:flex">{navIds.map(id => <button key={id} onClick={() => go(id)} className={`cursor-pointer border-0 bg-transparent text-sm font-medium transition ${active === id ? "text-primary" : "text-muted-foreground hover:text-foreground"}`}>{m.nav[id]}</button>)}</nav>
      <div className="hidden items-center gap-3 lg:flex"><LanguageSwitcher locale={locale} label={m.localeName}/><Button variant="cta" onClick={() => go("contact")}>{m.nav.quote}<ArrowRight/></Button></div>
      <div className="flex items-center gap-2 lg:hidden"><LanguageSwitcher locale={locale} label={m.localeName}/><Button variant="ghost" size="icon" onClick={() => setOpen(v => !v)} aria-label={open ? m.nav.menuClose : m.nav.menuOpen}>{open ? <X/> : <Menu/>}</Button></div>
    </div><div className="h-[3px]"/>
    <motion.div initial={false} animate={{ height: open ? "auto" : 0, opacity: open ? 1 : 0 }} className="overflow-hidden lg:hidden"><nav className="space-y-1 px-5 py-5">{navIds.map(id => <button key={id} onClick={() => go(id)} className="flex w-full cursor-pointer rounded-md border-0 bg-transparent px-3 py-3 text-left text-sm font-medium text-foreground hover:bg-surface">{m.nav[id]}</button>)}<Button variant="cta" className="mt-3 w-full" onClick={() => go("contact")}>{m.nav.quote}<ArrowRight/></Button></nav></motion.div>
  </header>;
}

